COMMENT ON COLUMN epilepsy_review.sex IS
    'Patient sex: female, male, intersex, or unknown.';
COMMENT ON COLUMN epilepsy_review.epilepsy_type IS
    'Epilepsy type: focal, generalised, combined, or unknown.';
