-- ========================================================================
-- BEGIN 05_create_table_epilepsy_review_grade.sql
-- ========================================================================

-- Computed seizure-control classification and completeness grading result for
-- an epilepsy annual review. The engine classifies seizure control from the
-- worst finding (increasing trend, weekly/daily frequency, or any status
-- epilepticus force uncontrolled; no seizures or a seizure-free trend give
-- seizure-free; otherwise controlled), and grades review completeness by
-- counting the documented required domains. A grade reflects the recorded
-- classification and the completeness of the review, not a diagnostic
-- judgement.

CREATE TABLE epilepsy_review_grade (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at TIMESTAMPTZ DEFAULT NULL,

    epilepsy_review_id UUID NOT NULL UNIQUE
        REFERENCES epilepsy_review(id) ON DELETE CASCADE,

    seizure_control VARCHAR(15) NOT NULL DEFAULT ''
        CHECK (seizure_control IN ('seizure-free', 'controlled', 'uncontrolled', '')),
    review_status VARCHAR(15) NOT NULL DEFAULT ''
        CHECK (review_status IN ('complete', 'partial', 'incomplete', '')),
    completeness_score INTEGER,

    graded_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TRIGGER trigger_epilepsy_review_grade_updated_at
    BEFORE UPDATE ON epilepsy_review_grade
    FOR EACH ROW
    EXECUTE FUNCTION set_updated_at();

COMMENT ON TABLE epilepsy_review_grade IS
    'Computed seizure-control classification and completeness grading result for an epilepsy annual review: seizure control, review-completeness status, and the count of documented required domains. 1:1 with the parent review.';
COMMENT ON COLUMN epilepsy_review_grade.id IS
    'Primary key UUID, auto-generated.';
COMMENT ON COLUMN epilepsy_review_grade.created_at IS
    'Timestamp when the row was created.';
COMMENT ON COLUMN epilepsy_review_grade.updated_at IS
    'Timestamp when the row was most recently updated.';
COMMENT ON COLUMN epilepsy_review_grade.deleted_at IS
    'Timestamp when the row was soft-deleted.';
COMMENT ON COLUMN epilepsy_review_grade.epilepsy_review_id IS
    'Foreign key to the parent epilepsy review (unique, 1:1).';
COMMENT ON COLUMN epilepsy_review_grade.seizure_control IS
    'Seizure-control classification: seizure-free, controlled, or uncontrolled.';
COMMENT ON COLUMN epilepsy_review_grade.review_status IS
    'Review completeness: complete, partial, or incomplete.';
COMMENT ON COLUMN epilepsy_review_grade.completeness_score IS
    'Count of documented required review domains.';
COMMENT ON COLUMN epilepsy_review_grade.graded_at IS
    'Timestamp when the engine last computed the grade.';

-- ========================================================================
-- END 05_create_table_epilepsy_review_grade.sql
-- ========================================================================

-- ========================================================================
-- BEGIN 06_create_table_epilepsy_review_grade_rule.sql
-- ========================================================================

-- Audit trail of every classification or completeness rule that fired during
-- grading. Each row records one rule firing with the section it concerns, the
-- category, and a human-readable description.

CREATE TABLE epilepsy_review_grade_rule (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at TIMESTAMPTZ DEFAULT NULL,

    epilepsy_review_grade_id UUID NOT NULL
        REFERENCES epilepsy_review_grade(id) ON DELETE CASCADE,

    rule_id VARCHAR(40) NOT NULL,
    section VARCHAR(20) NOT NULL DEFAULT ''
        CHECK (section IN ('seizure-control', 'completeness', '')),
    category VARCHAR(50) NOT NULL DEFAULT '',
    description VARCHAR(500) NOT NULL DEFAULT ''
);

CREATE INDEX epilepsy_review_grade_rule_grade_id_idx
    ON epilepsy_review_grade_rule (epilepsy_review_grade_id);

CREATE TRIGGER trigger_epilepsy_review_grade_rule_updated_at
    BEFORE UPDATE ON epilepsy_review_grade_rule
    FOR EACH ROW
    EXECUTE FUNCTION set_updated_at();

COMMENT ON TABLE epilepsy_review_grade_rule IS
    'Audit trail of every classification or completeness rule that fired during grading: section, category, and description.';
COMMENT ON COLUMN epilepsy_review_grade_rule.id IS
    'Primary key UUID, auto-generated.';
COMMENT ON COLUMN epilepsy_review_grade_rule.created_at IS
    'Timestamp when the row was created.';
COMMENT ON COLUMN epilepsy_review_grade_rule.updated_at IS
    'Timestamp when the row was most recently updated.';
COMMENT ON COLUMN epilepsy_review_grade_rule.deleted_at IS
    'Timestamp when the row was soft-deleted.';
COMMENT ON COLUMN epilepsy_review_grade_rule.epilepsy_review_grade_id IS
    'Foreign key to the parent grade.';
COMMENT ON COLUMN epilepsy_review_grade_rule.rule_id IS
    'Stable rule identifier (e.g. R-SEIZURE-CONTROL-UNCONTROLLED-01).';
COMMENT ON COLUMN epilepsy_review_grade_rule.section IS
    'Section the rule concerns: seizure-control or completeness.';
COMMENT ON COLUMN epilepsy_review_grade_rule.category IS
    'Subject category (e.g. control-classification, required-domain).';
COMMENT ON COLUMN epilepsy_review_grade_rule.description IS
    'Human-readable description of why the rule fired.';

-- ========================================================================
-- END 06_create_table_epilepsy_review_grade_rule.sql
-- ========================================================================

-- ========================================================================
-- BEGIN 07_create_table_epilepsy_review_grade_flag.sql
-- ========================================================================

-- Safety flags that fire independently of the seizure-control class and the
-- completeness status, each with a priority and a suggested action for the
-- clinician or governance team.

CREATE TABLE epilepsy_review_grade_flag (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at TIMESTAMPTZ DEFAULT NULL,

    epilepsy_review_grade_id UUID NOT NULL
        REFERENCES epilepsy_review_grade(id) ON DELETE CASCADE,

    flag_id VARCHAR(50) NOT NULL,
    category VARCHAR(30) NOT NULL DEFAULT ''
        CHECK (category IN (
            'specialist-review',
            'valproate-ppp',
            'status-epilepticus-history',
            'driving-safety',
            'mental-health',
            'sudep-not-documented',
            'poor-adherence',
            'asm-side-effects',
            'folic-acid-missing',
            'incomplete',
            'other',
            ''
        )),
    priority VARCHAR(10) NOT NULL DEFAULT ''
        CHECK (priority IN ('low', 'medium', 'high', '')),
    description VARCHAR(500) NOT NULL DEFAULT '',
    suggested_action VARCHAR(500) NOT NULL DEFAULT ''
);

CREATE INDEX epilepsy_review_grade_flag_grade_id_idx
    ON epilepsy_review_grade_flag (epilepsy_review_grade_id);

CREATE TRIGGER trigger_epilepsy_review_grade_flag_updated_at
    BEFORE UPDATE ON epilepsy_review_grade_flag
    FOR EACH ROW
    EXECUTE FUNCTION set_updated_at();

COMMENT ON TABLE epilepsy_review_grade_flag IS
    'Safety flags that fire independently of the seizure-control class and the completeness status, with priority and a suggested action for the clinician or governance team.';
COMMENT ON COLUMN epilepsy_review_grade_flag.id IS
    'Primary key UUID, auto-generated.';
COMMENT ON COLUMN epilepsy_review_grade_flag.created_at IS
    'Timestamp when the row was created.';
COMMENT ON COLUMN epilepsy_review_grade_flag.updated_at IS
    'Timestamp when the row was most recently updated.';
COMMENT ON COLUMN epilepsy_review_grade_flag.deleted_at IS
    'Timestamp when the row was soft-deleted.';
COMMENT ON COLUMN epilepsy_review_grade_flag.epilepsy_review_grade_id IS
    'Foreign key to the parent grade.';
COMMENT ON COLUMN epilepsy_review_grade_flag.flag_id IS
    'Stable flag identifier (e.g. F-VALPROATE-PPP-001).';
COMMENT ON COLUMN epilepsy_review_grade_flag.category IS
    'Flag category: specialist-review, valproate-ppp, status-epilepticus-history, driving-safety, mental-health, sudep-not-documented, poor-adherence, asm-side-effects, folic-acid-missing, incomplete, or other.';
COMMENT ON COLUMN epilepsy_review_grade_flag.priority IS
    'Priority: low, medium, high.';
